func tCps(c *port.Cells, b []byte) int32 {
	// The bytes of `b` as code points.
	var i int32 = 0
	for i < port.BlobLen(b) {
		port.CellsPush(c, port.BlobU8(b, i))
		i += 1
	}
	return 0
}

func tParse(c *enctx.Cfg, b []byte) int32 {
	// `cf-parse` over the bytes of `b`.
	var t *port.Cells = port.NewCells()
	tCps(t, b)
	return config.CfParse(t, c)
}

