func TestTheWordsOfEveryEnumKeyAreRead(emonT *testing.T) {
	var a *enctx.Cfg = enctx.NewCfg()
	var b *enctx.Cfg = enctx.NewCfg()
	var d *enctx.Cfg = enctx.NewCfg()
	var e *enctx.Cfg = enctx.NewCfg()
	tParse(a, port.TextBlob("ocr=always\nfurniture=policy\nassets=none\nasset-signatures=off\nocr-scope=full"))
	port.AssertEq(emonT, a.Ocr, 2, "always")
	port.AssertEq(emonT, a.Furn, 0, "policy")
	port.AssertEq(emonT, a.Level, 0, "none")
	port.AssertEq(emonT, a.Sigs, 0, "off")
	port.AssertEq(emonT, a.Scope, 0, "full")
	tParse(b, port.TextBlob("ocr=auto\nfurniture=keep\nassets=images"))
	port.AssertEq(emonT, b.Ocr, 1, "auto")
	port.AssertEq(emonT, b.Furn, 1, "keep")
	port.AssertEq(emonT, b.Level, 1, "images")
	tParse(d, port.TextBlob("keep-evidence=0\nrecord=yes\njs-ocr=11\njs-render=true"))
	port.AssertEq(emonT, d.Keep, 0, "a flag is 1 or nothing")
	port.AssertEq(emonT, d.Rec, 0, "yes is not 1")
	port.AssertEq(emonT, d.Jsocr, 0, "11 is not 1")
	port.AssertEq(emonT, d.Jsrender, 0, "true is not 1")
	tParse(e, port.TextBlob("keep-evidence=1"))
	port.AssertEq(emonT, e.Keep, 1, "one")
}

