func TestAnUnknownKeyOrALineWithoutAValueIsRefusedByName(emonT *testing.T) {
	tRefused(emonT, port.TextBlob("bogus=1"), "unknown option bogus")
	tRefused(emonT, port.TextBlob("ocr=auto\nbogus=1"), "unknown option bogus")
	tRefused(emonT, port.TextBlob("limit.nope=5"), "no limit named nope")
	tRefused(emonT, port.TextBlob("limit.=5"), "no limit named ")
	tRefused(emonT, port.TextBlob("novalue"), "option \"novalue\" has no value")
	tRefused(emonT, port.TextBlob("ocr=auto\nnovalue"), "option \"novalue\" has no value")
}

func TestALimitIsFoundByItsName(emonT *testing.T) {
	var t *port.Cells = port.NewCells()
	tCps(t, port.TextBlob("ref-depth"))
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 9), 4, "ref-depth")
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 8), -1, "a prefix of it")
	port.AssertEq(emonT, config.CfLimitFind(t, 4, 9), -1, "its tail")
	port.AssertEq(emonT, config.CfKeyFind(t, 0, 9), -1, "not a key")
}

func TestTheLimitsOfP104AreFoundByTheirNames(emonT *testing.T) {
	var t *port.Cells = port.NewCells()
	tCps(t, port.TextBlob("asset-placements"))
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 16), 13, "asset-placements")
	port.CellsDrop(t, 0)
	tCps(t, port.TextBlob("ocr-requests"))
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 12), 10, "ocr-requests")
	port.CellsDrop(t, 0)
	tCps(t, port.TextBlob("note-refs"))
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 9), 12, "note-refs")
	port.CellsDrop(t, 0)
	tCps(t, port.TextBlob("fonts-per-doc"))
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 13), 14, "fonts-per-doc")
	port.CellsDrop(t, 0)
	tCps(t, port.TextBlob("stage-ms"))
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 8), 15, "stage-ms")
	port.CellsDrop(t, 0)
	tCps(t, port.TextBlob("workers"))
	port.AssertEq(emonT, config.CfLimitFind(t, 0, 7), 16, "workers")
}

func TestFontsPerDocCannotBeRaisedPastItsSlab(emonT *testing.T) {
	tRefused(emonT, port.TextBlob("limit.fonts-per-doc=513"), "limit.fonts-per-doc is out of range 0..512")
}
